// ---------- NÚMEROS A PALABRAS ----------
const U=['cero','uno','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez','once','doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte','veintiuno','veintidós','veintitrés','veinticuatro','veinticinco','veintiséis','veintisiete','veintiocho','veintinueve'];
const D=['','','','treinta','cuarenta','cincuenta','sesenta','setenta','ochenta','noventa'];
const C=['','ciento','doscientos','trescientos','cuatrocientos','quinientos','seiscientos','setecientos','ochocientos','novecientos'];
function n2w(n){
  if(n<30) return U[n];
  if(n<100){const d=Math.floor(n/10),u=n%10;return D[d]+(u?' y '+U[u]:'');}
  if(n===100) return 'cien';
  if(n<1000){const c=Math.floor(n/100);return C[c]+(n%100?' '+n2w(n%100):'');}
  if(n<1e6){
    const m=Math.floor(n/1000);
    const mw=m===1?'mil':n2w(m).replace(/uno$/,'ún')+' mil';
    return mw+(n%1000?' '+n2w(n%1000):'');
  }
  if(n<1e9){
    const m=Math.floor(n/1e6);
    const mw=m===1?'un millón':n2w(m).replace(/uno$/,'ún')+' millones';
    return mw+(n%1e6?' '+n2w(n%1e6):'');
  }
  return String(n).split('').map(d=>U[+d]).join(' ');
}

// ---------- PRONUNCIACIÓN DE MARCAS / SIGLAS (ajusta probando) ----------
const dict = {
  'STEP2HAD':'Estép tu Jad',
  'Let Encrypt':'Lets Encrípt',
  'Well Architected Agent':'Uel Arquitéctid Éyent',
  'Rent A Human':'Rent ei Jiúman',
  'HP Color LaserJet Enterprise':'hache pe Color Léiser Yet Énterprais',
  'LaserJet Enterprise MFP':'Léiser Yet Énterprais eme efe pe',
  'Enterprise':'Énterprais',
  'LaserJet':'Léiser Yet',
  'NVIDIA':'Envidia',
  'AWS':'a doble u ese',
  'HP':'hache pe',
  'MFP':'eme efe pe',
  'RwLock':'erre u loc',
  'lock free':'loc fri',
  'crossbeam':'crosbim',
  'macsNova':'Maks Nova',
  'DeepMind':'Dipmaind',
  'Hella Gutmann':'Jela Gutman',
  'Surface':'Sérfis',
  'Microsoft':'Máicrosoft',
  'Google':'Gúgl',
  'Lennon':'Lénon'
};
const keys = Object.keys(dict).sort((a,b)=>b.length-a.length)
  .map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
const dictRe = new RegExp('(?<![A-Za-zÁ-ú0-9])('+keys.join('|')+')(?![A-Za-zÁ-ú0-9])','gi');
const dictLower = Object.fromEntries(Object.entries(dict).map(([k,v])=>[k.toLowerCase(),v]));

const MESES='enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre';

return items.map(item => {
  // Texto que viene del nodo Redactor (LangChain)
  let inputText = item.json.text || '';
  if (typeof inputText !== 'string') inputText = '';
  let t = inputText;

  // 0. SALTOS DE LÍNEA ESCAPADOS (\n literal) -> saltos reales
  t = t.replace(/\\r\\n|\\n|\\r/g, '\n').replace(/\r\n?/g, '\n');

  // 1. NATURALIZACIÓN (símbolos a palabras)
  t = t
    .replace(/&/g, ' y ')
    .replace(/</g, ' menor que ')
    .replace(/>/g, ' mayor que ')
    .replace(/=/g, ' igual a ')
    .replace(/\+/g, ' más ')
    .replace(/(\d[\d.,]*)\s?€/g, '$1 euros')
    .replace(/(\d[\d.,]*)\s?\$/g, '$1 dólares')
    .replace(/\$\s?(\d[\d.,]*)/g, '$1 dólares')
    .replace(/%/g, ' por ciento ');

  // 2. LIMPIEZA DE "BASURA" DEL LLM
  t = t
    .replace(/\*\*/g, '')
    .replace(/#/g, '')
    .replace(/`/g, '')
    .replace(/["'“”‘’]/g, '');

  // 3. GESTIÓN DE PAUSAS: cada párrafo termina en punto, sin dobles puntos
  t = t.split(/\n+/)
    .map(p => p.trim())
    .filter(Boolean)
    .map(p => /[.!?…:]$/.test(p) ? p : p + '.')
    .join(' ');
  t = t.replace(/\.(\s*\.)+/g, '.');   // ". ." -> "."

  // 4. MARCAS Y SIGLAS
  t = t.replace(dictRe, m => dictLower[m.toLowerCase()] || m);

  // 5. PALABRAS EN MAYÚSCULAS NO RESUELTAS (REFACTIKA -> Refactika)
  t = t.replace(/\b[A-ZÁÉÍÓÚÑ]{4,}\b/g, w => w[0] + w.slice(1).toLowerCase());

  // 6. NÚMEROS A PALABRAS
  t = t.replace(new RegExp('\\b1 de (' + MESES + ')\\b', 'gi'), 'primero de $1');
  t = t.replace(/(\d)\.(?=\d{3}(?!\d))/g, '$1');   // 2.500 -> 2500
  t = t.replace(/(\d+),(\d+)/g, (_, a, b) => n2w(+a) + ' coma ' + b.split('').map(d => U[+d]).join(' '));
  t = t.replace(/\d+/g, n => n2w(+n));

  // 6b. MAYÚSCULA AL INICIO DE CADA FRASE
  t = t.replace(/(^|[.!?]\s+|[¡¿])([a-záéíóúñ])/g, (m, a, b) => a + b.toUpperCase());

  // 7. NORMALIZACIÓN FINAL
  t = t.replace(/\s+/g, ' ').replace(/\s+([,.;:!?])/g, '$1').trim();

  item.json.cleanedTextForTTS = t;
  return item;
});

