const inputData = items[0]?.json || {};

// 1. Resúmenes (vienen del Final Aggregate, metidos en 'data')
const summaries = inputData.data || [];

// 2. Noticias seleccionadas (vienen del News Analyzer, dentro de 'output')
const selectedNews = inputData.output?.top_15_news || [];

// 3. Historial (viene del Filtrado Historial)
const historicalNews = inputData.historial || [];

const todayNews = [];

// Cruzamos los datos por ID
for (const news of selectedNews) {

  // Buscamos en el array de resúmenes el que tenga el mismo ID
  const matchedData = summaries.find(s => s.output?.id === String(news.id));

  todayNews.push({
    title: news.title,
    summary: matchedData ? matchedData.output.summary : "Resumen no disponible"
  });
}

return [{
  json: {
    today_news: todayNews,
    historical_news: historicalNews
  }
}];

// 1. Calcular fecha límite una sola vez (más eficiente)
const sevenDaysAgo = $now.minus({ days: 7 }).toFormat('yyyy-MM-dd');

// Array final donde guardaremos solo lo que nos sirve
const cleanedHistory = [];

// Obtener datos (Asegúrate de que 'propertyName' es el nombre real del campo que viene de Redis)
const rawData = items[0]?.json?.propertyName;

if (rawData && Array.isArray(rawData)) {
  // 2. UNA SOLA PASADA (Bucle único)
  for (const jsonString of rawData) {
    try {
      // Parseamos el string a objeto
      const parsed = JSON.parse(jsonString);

      // Normalizamos: si es un objeto suelto, lo metemos en un array temporal para procesarlo igual
      const articles = Array.isArray(parsed) ? parsed : [parsed];

      // Procesamos los artículos de este bloque
      for (const article of articles) {
        // 3. FILTRADO Y MAPEO INMEDIATO
        // Si tiene fecha y es reciente, lo guardamos. Si no, lo descartamos al instante.
        if (article && article.pubDate && article.pubDate >= sevenDaysAgo) {
          cleanedHistory.push({
            title: article.title,
            pubDate: article.pubDate
          });
        }
      }
    } catch (e) {
      // Si un JSON está corrupto, lo ignoramos y seguimos con el siguiente
      continue;
    }
  }
}

return [{
  json: {
    historial: cleanedHistory
  }
}];

// 1. Obtener datos de los nodos anteriores
const todayArticles = $('Aggregate').first().json.data || [];
const historyRaw = $('Filtrado Historial').first().json.historial || [];

// 2. LIMPIEZA DE NOTICIAS DE HOY
// Solo pasamos Título y Link (el contenido NO es necesario para elegir el Top 15)
// Esto reduce el uso de tokens en un ~90%
const cleanToday = todayArticles.map((art, index) => {
  return {
    id: art.id,
    title: art.title ? art.title.trim() : "Sin título",
    link: art.link || ""
  };
});

// 3. LIMPIEZA Y DEDUPLICACIÓN DEL HISTORIAL
// El historial a veces trae duplicados que confunden a la IA
const historyMap = new Map();
historyRaw.forEach(art => {
  if (art.title) {
    const normalizedTitle = art.title.toLowerCase().trim();
    if (!historyMap.has(normalizedTitle)) {
      historyMap.set(normalizedTitle, {
        title: art.title.trim(),
        date: art.pubDate || ""
      });
    }
  }
});
const cleanHistory = Array.from(historyMap.values());

// 4. SALIDA OPTIMIZADA
return [{
  json: {
    data: cleanToday,
    historial: cleanHistory,
    stats: {
      today_count: cleanToday.length,
      history_count: cleanHistory.length
    }
  }
}];

