const { execSync } = require('child_process');
const fs = require('fs');

// 1. Obtener el buffer del audio WAV recibido
const inputBuffer = await helpers.getBinaryDataBuffer(0, 'data');
const inputPath = '/tmp/input_audio.wav';
const outputPath = '/tmp/speech.opus';

// 2. Guardar temporalmente en el sistema de archivos del contenedor
fs.writeFileSync(inputPath, inputBuffer);

// 3. Convertir a Opus mono 48kHz optimizado para WhatsApp
execSync(`ffmpeg -y -i ${inputPath} -c:a libopus -ac 1 -ar 48000 -b:a 64k ${outputPath}`);

// 4. Cargar el resultado y limpiar temporales
const outputBuffer = fs.readFileSync(outputPath);
if (fs.existsSync(inputPath)) fs.unlinkSync(inputPath);
if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);

// 5. Retornar el audio convertido a n8n
return {
  json: $json,
  binary: {
    data: await helpers.prepareBinaryData(outputBuffer, 'speech.opus', 'audio/ogg')
  }
};

