return $input.all().map(item => {
  let text = item.json.content || "";

  // 1. Normalización Unicode (convierte guiones raros, espacios invisibles y caracteres a ASCII estándar)
  text = text.normalize("NFKC").replace(/\u2011/g, "-");

  // 2. Elimina el menú de navegación superior y enlaces de cabecera
  text = text.replace(/Brut version [a-f0-9]+\s*\* \[Contribute\][\s\S]*?\n\n/gi, '');
  text = text.replace(/^\s*[\*\-]\s*\[(Contribute|Download)\]\(.*?\)\s*\n?/gm, '');

  // 3. Elimina bloques de licencias de software (MIT)
  text = text.replace(/```[\s\S]*?Permission is hereby granted[\s\S]*?```/gi, '');
  text = text.replace(/Permission is hereby granted[\s\S]*?OF THIS SOFTWARE\./gi, '');

  // 4. Limpia títulos Markdown con anclas conservando el nivel de encabezado (#)
  // Ej: "## [2.1](#slug) Identifying" -> "## Identifying"
  text = text.replace(/^(#+)\s*\[[\d\.]+\]\([^)]+\)\s*/gm, '$1 ');

  // 5. Limpia enlaces de ancla en línea conservando el texto
  // Ej: "[shared scripts](#extending-the-environment)" -> "shared scripts"
  text = text.replace(/\[([^\]]+)\]\(#[^)]+\)/g, '$1');

  // 6. Limpia espacios en blanco al final de línea
  text = text.replace(/[ \t]+$/gm, '');

  // 7. Normaliza saltos de línea excesivos (máximo 2 consecutivos)
  text = text.replace(/\n{3,}/g, '\n\n');

  return {
    json: {
      ...item.json,
      content_prelimpio: text.trim()
    }
  };
});

